// Normalize error payloads from any upstream workflow. Strip anything secret-shaped.
const r = $input.first().json;
const err = r.error || r.err || null;
const correlationId = r.correlationId || r.request?.principal?.correlationId || null;
const scrub = (v) => {
  if (!v || typeof v !== 'object') return v;
  const copy = Array.isArray(v) ? [] : {};
  for (const [k, val] of Object.entries(v)) {
    if (/token|secret|password|authorization|api[_-]?key/i.test(k)) copy[k] = '[REDACTED]';
    else copy[k] = scrub(val);
  }
  return copy;
};
const payload = {
  correlationId,
  code: err?.code || 'unknown_error',
  message: err?.message || 'Unknown failure',
  context: scrub(r.context || {}),
  operationIds: r.operationIds || []
};
return [{ json: payload }];

const err = $('Normalize error').item.json;
const op = $json;
const detail = op && !op.error ? `Last operation ${op.operationId}: state=${op.state}, action=${op.action}` : 'No operation state available.';
return [{ json: {
  correlationId: err.correlationId,
  report: `Error ${err.code}: ${err.message}. ${detail}`,
  code: err.code,
  retryable: ['rate_limited','backend_unavailable','timeout'].includes(err.code)
} }];
